import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { authApi } from '../api/client';
import Toast from '../components/Toast';
import { Cpu, Mail, Lock, Eye, EyeOff, LogIn, CheckCircle2, ShieldCheck, Sparkles, UserCheck, ArrowRight } from 'lucide-react';

const LoginPage = ({ onLoginSuccess }) => {
  const navigate = useNavigate();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState(null);

  // Pre-configured official demo accounts for quick testing
  const demoAccounts = [
    {
      role: 'Shift Engineer',
      name: 'Anita Desai',
      email: 'engineer@textwin.ai',
      pass: 'password123',
      color: '#38bdf8',
      desc: 'Real-time telemetry, IoT sensors & RUL monitoring',
    },
    {
      role: 'Plant Manager',
      name: 'Suresh Mehta',
      email: 'manager@textwin.ai',
      pass: 'password123',
      color: '#8b5cf6',
      desc: 'Plant hierarchy, what-if simulations & factory OEE',
    },
    {
      role: 'Supervisor',
      name: 'Rajesh Kumar',
      email: 'supervisor@textwin.ai',
      pass: 'password123',
      color: '#10b981',
      desc: 'Maintenance alerts, work orders & shift dispatch',
    },
    {
      role: 'System Admin',
      name: 'Vikram Sharma',
      email: 'admin@textwin.ai',
      pass: 'password123',
      color: '#f59e0b',
      desc: 'Full administrative access & system settings',
    },
  ];

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!email || !password) {
      setToast({ message: 'Please provide both your email address and password', type: 'error' });
      return;
    }

    try {
      setLoading(true);
      const res = await authApi.login({ email, password });

      if (res.data.success) {
        localStorage.setItem('token', res.data.token);
        localStorage.setItem('user', JSON.stringify(res.data.user));

        if (onLoginSuccess) onLoginSuccess(res.data.user);
        setToast({ message: `Welcome back, ${res.data.user.name}! Redirecting...`, type: 'success' });
        setTimeout(() => navigate('/'), 600);
      }
    } catch (err) {
      const msg = err.response?.data?.message || 'Login failed. Please check your credentials.';
      setToast({ message: msg, type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleSelectDemoAccount = (account) => {
    setEmail(account.email);
    setPassword(account.pass);
    setToast({
      message: `Selected ${account.role} (${account.email}). Click Sign In!`,
      type: 'info',
    });
  };

  return (
    <div className="auth-page-container">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="auth-wrapper">
        {/* Left Side: Brand Visual & Features Showcase */}
        <div className="auth-hero-section">
          <div className="auth-hero-content">
            <div className="hero-badge">
              <Sparkles size={15} /> NEXT-GEN INDUSTRY 4.0 PLATFORM
            </div>

            <h1 className="hero-title">
              Tex<span className="hero-highlight">Twin</span> AI Digital Twin
            </h1>
            <p className="hero-description">
              Continuous IoT sensor monitoring, predictive RUL analytics, real-time thread break detection, and what-if simulation for smart textile weaving facilities.
            </p>

            <div className="hero-stats-grid">
              <div className="stat-pill">
                <div className="stat-value">99.4%</div>
                <div className="stat-label">AI RUL Accuracy</div>
              </div>
              <div className="stat-pill">
                <div className="stat-value">&lt; 2s</div>
                <div className="stat-label">Telemetry Latency</div>
              </div>
              <div className="stat-pill">
                <div className="stat-value">6 Mills</div>
                <div className="stat-label">Connected Facilities</div>
              </div>
            </div>

            <div className="auth-feature-list">
              <div className="feature-item">
                <CheckCircle2 size={18} className="feature-icon" />
                <span>Real-Time Sensor Telemetry (RPM, Vibration, Temp, Tension)</span>
              </div>
              <div className="feature-item">
                <CheckCircle2 size={18} className="feature-icon" />
                <span>AI Remaining Useful Life (RUL) & Root Cause Diagnostics</span>
              </div>
              <div className="feature-item">
                <CheckCircle2 size={18} className="feature-icon" />
                <span>Interactive What-If Simulation & Production Forecasting</span>
              </div>
            </div>
          </div>
        </div>

        {/* Right Side: High-Tech Login Card */}
        <div className="auth-card-container">
          <div className="auth-card">
            <div className="auth-header">
              <div className="auth-logo-box">
                <Cpu size={30} />
              </div>
              <h2 className="auth-heading">Sign In to TexTwin</h2>
              <p className="auth-subheading">Enter your original email or select an official access account</p>
            </div>

            {/* Form */}
            <form onSubmit={handleSubmit} className="auth-form">
              <div className="form-group">
                <label className="form-label">
                  <span>Work Email Address</span>
                  <span className="email-hint">(Original & Custom Emails Allowed)</span>
                </label>
                <div className="input-icon-wrapper">
                  <Mail size={18} className="input-left-icon" />
                  <input
                    type="email"
                    className="form-control auth-input"
                    placeholder="Enter your email (e.g. user@gmail.com or engineer@textwin.ai)"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    autoComplete="email"
                  />
                </div>
              </div>

              <div className="form-group">
                <div className="label-between">
                  <label className="form-label">Password</label>
                  <Link to="/forgot-password" className="forgot-password-link">
                    Forgot password?
                  </Link>
                </div>
                <div className="input-icon-wrapper">
                  <Lock size={18} className="input-left-icon" />
                  <input
                    type={showPassword ? 'text' : 'password'}
                    className="form-control auth-input"
                    placeholder="Enter password (default: password123)"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    autoComplete="current-password"
                  />
                  <button
                    type="button"
                    className="password-toggle-btn"
                    onClick={() => setShowPassword(!showPassword)}
                    title={showPassword ? 'Hide Password' : 'Show Password'}
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>

              <button type="submit" className="btn btn-primary btn-block auth-submit-btn" disabled={loading}>
                {loading ? (
                  <span>Authenticating Session...</span>
                ) : (
                  <>
                    <LogIn size={18} />
                    <span>Access Digital Twin</span>
                    <ArrowRight size={16} />
                  </>
                )}
              </button>
            </form>

            {/* Official Access Credentials Section */}
            <div className="official-credentials-box">
              <div className="credentials-header">
                <ShieldCheck size={16} className="shield-icon" />
                <span>OFFICIAL DEMO ACCESS CREDENTIALS</span>
              </div>
              <p className="credentials-subtext">Click any official role below to auto-fill verified access credentials:</p>

              <div className="demo-accounts-grid">
                {demoAccounts.map((acc, index) => (
                  <div
                    key={index}
                    className={`demo-account-card ${email === acc.email ? 'active' : ''}`}
                    onClick={() => handleSelectDemoAccount(acc)}
                  >
                    <div className="demo-card-top">
                      <span className="demo-role-badge" style={{ backgroundColor: `${acc.color}20`, color: acc.color, borderColor: `${acc.color}40` }}>
                        {acc.role}
                      </span>
                      <UserCheck size={14} style={{ color: acc.color }} />
                    </div>
                    <div className="demo-user-name">{acc.name}</div>
                    <div className="demo-user-email">{acc.email}</div>
                    <div className="demo-user-pass">Password: <code>{acc.pass}</code></div>
                  </div>
                ))}
              </div>
            </div>

            <div className="auth-footer-text">
              <ShieldCheck size={14} /> Encrypted 256-Bit SSL Telemetry Protocol & Roles-Based Access Control
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
